#include <iostream>
#include <string>
struct ExpensiveObject {
  std::string data; 
  ExpensiveObject() : data("default") {std::cout << "ExpensiveObject constructed\n";}
  ExpensiveObject(const ExpensiveObject& other) : data(other.data) {std::cout << "ExpensiveObject copy constructed\n";}
  ExpensiveObject(ExpensiveObject&& other) : data(std::move(other.data)) {std::cout << "ExpensiveObject move constructed\n";}
  ~ExpensiveObject() {std::cout << "ExpensiveObject destructed\n";}
};

ExpensiveObject createExpensiveObject() {
  ExpensiveObject obj; 
  obj.data = "Hello";
  return obj;
}

int main() {
  ExpensiveObject myObj = createExpensiveObject();
  return 0;
}
